 for(const r of data.routes){const entry=data.catalog.find(x=>x.id===r.id),a=placements[entry.fromId],b=placements[entry.toId],curve=placements[r.id],anchor=data.layout.networkTiles[r.id],e=g.edges[r.gameId];if(e&&Number.isInteger(e.owner)&&anchor){svg+=component(netImage(e.networkId,g.players[e.owner].color),{...anchor,w:.0495,h:r.type==='rail'?.022:.019},g.players[e.owner].name+' '+r.from+'—'+r.to);if(e.bonusRemaining&&resources[e.bonusType])svg+=component(`assets/board-components/resource/${resources[e.bonusType]}.webp`,{x:anchor.x,y:anchor.y+.018,w:.016,h:.016},e.bonusType)}if(curve?.c1&&curve?.c2)svg+=`<path class="hit" data-route="${r.id}" d="M ${a.x*2000} ${a.y*2000} C ${curve.c1.x*2000} ${curve.c1.y*2000} ${curve.c2.x*2000} ${curve.c2.y*2000} ${b.x*2000} ${b.y*2000}"/>`;}
 for(const c of data.catalog.filter(x=>x.kind==='merchant')){const city=data.locations.find(l=>l.id===c.parentId).name,v=g.setup.merchant[city],original=g.setup.merchantOriginal?.[city]||v,used=g.merchantUsed[city],combo=original.includes('/'),base=combo?(original.includes('$12')?'market-blank-or-combo':'market-car-or-combo'):marketArt[original.split(' · ')[0]];if(base)svg+=component(`assets/board-components/market/${base}-${used?'back':'front'}-v01.webp`,placements[c.id],city+' '+v)}
 for(const l of data.locations.filter(l=>l.oil)){const p=data.layout.oilTiles[l.id]||placements[l.id],q=g.setup.oil[l.name],city=g.oilCities[l.name],rig={...p,w:.045,h:.045};svg+=component('assets/board-components/oil/oil-field-rig-retouched.webp',rig,'유전');const face=q.revealed?Object.entries(oilArt).find(([k])=>q.value.startsWith(k))?.[1]:'oil-field-01-rig-shared-back-v01';if(city)svg+=component(image('k5',g.players[city.owner].color,city.flipped),rig,'오일 시티');else if(face)svg+=component(`assets/board-components/oil/${face}.webp`,{...rig,w:.051,h:.051},q.revealed?q.value:'미공개 유전');if(q.revealed){const n=city?city.resource:g.oilfields[l.name],anchor=data.layout.oilStackAnchors[l.id]||{x:p.x+.022,y:p.y+.02};svg+=`<text x="${anchor.x*2000}" y="${anchor.y*2000}" fill="#fff" stroke="#152126" stroke-width="7" paint-order="stroke" font-size="27" font-weight="bold">${n}</text>`}svg+=rect(rig,`class="hit slot-hit" data-oil="${l.id}"`)}
