document.addEventListener('click',e=>{const action=e.target.closest('[data-action]'),choice=e.target.closest('[data-choice]');if(action)task(()=>{options=F.list(g);filterType=action.dataset.action;$('#pickerTitle').textContent=filterType;$('#search').value='';paintChoices();$('#picker').showModal()});if(choice){proposal=options[Number(choice.dataset.choice)];$('#picker').close();render()}if(e.target.id==='decide')task(()=>{proposal=F.choose(g);render()});if(e.target.id==='cancelProposal'){proposal=null;render()}if(e.target.id==='execute')task(()=>{const next=F.perform(g,data,proposal);history.push(structuredClone(g));history=history.slice(-12);g=next;proposal=null;store();render()})});
$('#search').oninput=paintChoices;$('#closePicker').onclick=()=>$('#picker').close();$('#personalOwner').onchange=renderPersonal;$('#undo').onclick=()=>{if(!history.length)return;g=history.pop();proposal=null;store();render()};$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(g,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pittsburgh-four-player-save.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};$('#import').onchange=async e=>{try{const value=F.validate(JSON.parse(await e.target.files[0].text()));if(!confirm('현재 4인 진행을 이 저장으로 바꿀까요?'))return;if(g)history.push(structuredClone(g));g=value;proposal=null;store();render()}catch(e){$('#message').textContent=e.message}finally{$('#import').value=''}};
